<script setup lang="ts">
import{ref,watch,inject}from'vue';import{useRoute}from'vue-router';import{ApiError}from'../api';import{useTicketWork}from'../ticket-work';import{ticketReadDenied,isObjectReadDenied}from'../ticket-access';import{reopenApi,validReopen,type ReopenRequest}from'../ticket-reopen-api';import type{TicketDetail}from'../ticket-api';
const props=defineProps<{ticket:TicketDetail}>(),route=useRoute(),work=useTicketWork(()=>route.fullPath),deny=inject(ticketReadDenied,undefined),items=ref<ReopenRequest[]>([]),total=ref(0),page=ref(1);
const labels:Record<string,string>={PENDING_REVIEW:'重开申请待审核（尚未重开）',APPROVED:'已批准并建立新轮次',REJECTED:'重开申请已拒绝',NO_LONGER_APPLICABLE:'申请已不适用'};
const stamp=()=>JSON.stringify([props.ticket.id,props.ticket.roundId,props.ticket.rowVersion,props.ticket.currentReopen?.reopenRequestId]);
async function load(next=1){const expected=stamp(),scope=work.begin(()=>expected===stamp());items.value=[];total.value=0;try{const r=await reopenApi.history(props.ticket.id,next);if(!scope.current())return;if(!Array.isArray(r.items)||r.items.some(x=>!validReopen(x,{...props.ticket,roundId:x.sourceRoundId})))throw new ApiError(503,'REOPEN_PROJECTION_INVALID','重开申请公开投影无法确认');items.value=r.items;total.value=r.total;page.value=r.page}catch(e){if(scope.current()&&isObjectReadDenied(e))deny?.();work.fail(e,scope)}finally{scope.finish()}}
watch(stamp,()=>void load(),{immediate:true});
</script>
<template><section class="panel ticket-reopens"><h2>重开申请与公开决定</h2><p v-if="!ticket.readOnly && ticket.currentReopen?.state==='PENDING_REVIEW'" class="notice">申请不等于重开成功：源轮仍已关闭并冻结，只有批准后才建立新轮。审批/内部接单不算首次人工响应。</p><p v-if="work.message.value" role="alert">{{work.message.value}}</p><article v-for="r in items" :key="r.reopenRequestId" class="record-entry reopen-entry"><h3>{{labels[r.state]}}</h3><p>源轮 {{r.sourceRoundId}} · 关闭操作 {{r.sourceClosureOperationId}} · 申请 {{r.reopenRequestId}} · {{r.requestedAt}} · 申请截止 {{r.reopenDeadline}}</p><p style="white-space:pre-wrap">{{r.reason}}</p><p v-if="r.decision" style="white-space:pre-wrap">公开决定 {{r.decision.reason}} · {{r.decision.decidedAt}} · 新轮 {{r.decision.newRoundId||'未建立'}} · 确认等级 {{r.decision.priority||'不适用'}}</p></article><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev, pager, next, total" @current-change="load"/><el-button :disabled="work.busy.value" @click="load(page)">重新查询重开申请</el-button></section></template>
